corpus_block("test-geom-boxplot.R: geom_boxplot range includes all outliers", {
  dat <- data_frame(x = 1, y = c(-(1:20) ^ 3, (1:20) ^ 3) )
  .plot("test-geom-boxplot.R: geom_boxplot range includes all outliers #1", ggplot(dat, aes(x, y)) + geom_boxplot())
  p <- ggplot_build(ggplot(dat, aes(x,y)) + geom_boxplot())
  miny <- p@layout$panel_params[[1]]$y.range[1]
  maxy <- p@layout$panel_params[[1]]$y.range[2]
  .plot("test-geom-boxplot.R: geom_boxplot range includes all outliers #2", ggplot(dat, aes(x, y)) + geom_boxplot(outliers = FALSE))
  p <- ggplot_build(ggplot(dat, aes(x, y)) + geom_boxplot(outliers = FALSE))
  miny <- p@layout$panel_params[[1]]$y.range[1]
  maxy <- p@layout$panel_params[[1]]$y.range[2]
})

corpus_block("test-geom-boxplot.R: geom_boxplot works in both directions", {
  dat <- data_frame(x = 1, y = c(-(1:20) ^ 3, (1:20) ^ 3) )
  .plot("test-geom-boxplot.R: geom_boxplot works in both directions #1", p <- ggplot(dat, aes(x, y)) + geom_boxplot())
  x <- get_layer_data(p)
  .plot("test-geom-boxplot.R: geom_boxplot works in both directions #2", p <- ggplot(dat, aes(y, x)) + geom_boxplot())
  y <- get_layer_data(p)
  x$flipped_aes <- NULL
  y$flipped_aes <- NULL
})

