corpus_block("test-geom-boxplot.R: boxes with variable widths do not overlap", {
  df <- data_frame(
      value = 1:12,
      group = rep(c("a", "b", "c"), each = 4L),
      subgroup = rep(c("A", "B"), times = 6L)
    )
  .plot("test-geom-boxplot.R: boxes with variable widths do not overlap #1", p <- ggplot(df, aes(group, value, colour = subgroup)) +
      geom_boxplot(varwidth = TRUE))
  d <- get_layer_data(p)[c("xmin", "xmax")]
  xid <- find_x_overlaps(d)
})

